commit.message:
[dawn][emscripten] Add texture-component-swizzle support

Tested locally with the following code:

  wgpu::TextureViewDescriptor viewDesc{};
  wgpu::TextureComponentSwizzleDescriptor swizzleDesc{};
  swizzleDesc.swizzle.r = wgpu::ComponentSwizzle::One;
  swizzleDesc.swizzle.g = wgpu::ComponentSwizzle::One;
  swizzleDesc.swizzle.b = wgpu::ComponentSwizzle::One;
  swizzleDesc.swizzle.a = wgpu::ComponentSwizzle::One;
  viewDesc.nextInChain = &swizzleDesc;

  wgpu::RenderPassColorAttachment attachment{
      .view = surfaceTexture.texture.CreateView(&viewDesc),
      .loadOp = wgpu::LoadOp::Clear,
      .storeOp = wgpu::StoreOp::Store};

Bug: 414312052
Change-Id: Ic9c499da27bd3276b394443cbccfa7c57b53ee78

